const input = $input.first().json;
const conversations = input.data?.items || input.data || [];

const sevenDaysAgo = Date.now() - (7 * 24 * 60 * 60 * 1000);

const filtered = conversations.filter(c => {
  const updatedRecently = (c.updated_at * 1000) > sevenDaysAgo; // Crisp uses seconds not ms
  return updatedRecently;
});

const signals = filtered.map(c => ({
  topic: c.meta?.subject || c.topic || '(no topic)',
  lastMessage: c.last_message?.content || '',
  segments: c.meta?.segments || [],
  merchantName: c.meta?.nickname || '',
  shopifyPlan: c.meta?.data?.shopify_plan || '',
  appPlan: c.meta?.data?.app_plan || '',
  monthlyRevenue: c.meta?.data?.last_30_days_app_revenue_usd || 0,
  gmv: c.meta?.data?.last_month_gmv_usd || 0,
  state: c.status || c.state,
  updatedAt: new Date(c.updated_at * 1000).toISOString().split('T')[0]
}));

console.log(`Total: ${conversations.length} | Filtered: ${filtered.length}`);

return [{ json: { signals, count: signals.length } }];

