const response = $input.first().json;
const rawText = response.content?.[0]?.text || '';

const today = new Date().toISOString().split('T')[0];
const sevenDaysAgo = new Date(Date.now() - 7*24*60*60*1000).toISOString().split('T')[0];

let parsed;
try {
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch(e) {
  return [{
    json: {
      source: 'crisp_eb',
      signals: [],
      itemCount: 0,
      dateRange: `${sevenDaysAgo} to ${today}`,
      status: 'error',
      error: `Parse failed: ${e.message}`
    }
  }];
}

// Convert Crisp-specific schema → Collector Base Prompt schema
const signals = [];

// Pain points → signals
for (const p of (parsed.painPoints || [])) {
  signals.push({
    id: `crisp-eb-pain-${signals.length + 1}`,
    type: 'pain_point',
    content: p.contentOpportunity || p.theme,
    evidence: p.verbatimSignal || '',
    confidence: p.frequency >= 3 ? 'high' : p.frequency >= 2 ? 'medium' : 'low',
    product: 'Easy Bundles',
    merchantCount: p.frequency || 1,
    merchantExamples: p.merchantExamples || [],
    origin: {
      name: 'Crisp live chat — Easy Bundles',
      author: '',
      date: today,
      url: `https://app.crisp.chat/website/b3910a47-66c1-43ab-b044-8b97762f4a6b/inbox/`
    }
  });
}

// Positive signals → customer_signal type
for (const p of (parsed.positiveSignals || [])) {
  signals.push({
    id: `crisp-eb-win-${signals.length + 1}`,
    type: 'customer_signal',
    content: p.signal || p.theme,
    evidence: `${p.merchantExample}: ${p.signal}`,
    confidence: 'medium',
    product: 'Easy Bundles',
    origin: {
      name: 'Crisp live chat — Easy Bundles',
      author: p.merchantExample || '',
      date: today,
      url: `https://app.crisp.chat/website/b3910a47-66c1-43ab-b044-8b97762f4a6b/inbox/`
    }
  });
}

// HVC signals → commercial type
for (const h of (parsed.highValueMerchantSignals || [])) {
  signals.push({
    id: `crisp-eb-hvc-${signals.length + 1}`,
    type: 'commercial',
    content: h.signal,
    evidence: `${h.merchant} (GMV: $${h.gmv}, App Revenue: $${h.appRevenue}): ${h.signal}`,
    confidence: 'high',
    product: 'Easy Bundles',
    origin: {
      name: 'Crisp live chat — Easy Bundles',
      author: h.merchant || '',
      date: today,
      url: `https://app.crisp.chat/website/b3910a47-66c1-43ab-b044-8b97762f4a6b/inbox/`
    }
  });
}

return [{
  json: {
    source: 'crisp_eb',
    signals,
    crispSummary: parsed.crispSummary || '',
    contentOpportunities: parsed.contentOpportunities || [],
    itemCount: signals.length,
    dateRange: `${sevenDaysAgo} to ${today}`,
    status: signals.length > 0 ? 'success' : 'empty'
  }
}];

